def _norm(value):
    text = unicodedata.normalize('NFKD', str(value or ''))
    return ''.join(ch for ch in text if not unicodedata.combining(ch)).strip().casefold()


def _load_english_names(apps, schema_editor):
    Magia = apps.get_model('home', 'TbMagia')
    Item = apps.get_model('home', 'TbItemMagico')
    data_dir = Path(__file__).resolve().parents[1] / 'data'

    spell_path = data_dir / 'magias_nomes_ingles.csv'
    if spell_path.exists():
        with spell_path.open('r', encoding='utf-8-sig', newline='') as handle:
            rows = list(csv.DictReader(handle))
        lookup = {}
        for row in rows:
            pt = row.get('final') or row.get('adaptado') or row.get('traduzido')
            en = (row.get('en') or '').strip()
            if pt and en:
                lookup.setdefault(_norm(pt), en)
        for spell in Magia.objects.all().only('pk', 'nome', 'nome_ingles'):
            english = lookup.get(_norm(spell.nome))
            if english and spell.nome_ingles != english:
                spell.nome_ingles = english
                spell.save(update_fields=['nome_ingles'])

    item_path = data_dir / 'itens_magicos_nomes_ingles.csv'
    if item_path.exists():
        with item_path.open('r', encoding='utf-8-sig', newline='') as handle:
            lookup = {
                (row.get('db_slug') or '').strip(): (row.get('en_name') or '').strip()
                for row in csv.DictReader(handle)
                if (row.get('db_slug') or '').strip() and (row.get('en_name') or '').strip()
            }
        for item in Item.objects.filter(slug__in=lookup):
            item.nome_ingles = lookup[item.slug]
            item.save(update_fields=['nome_ingles'])


def _dedupe_magic_items(apps, schema_editor):
    Item = apps.get_model('home', 'TbItemMagico')
    Inventory = apps.get_model('home', 'TbPersonagemItem')
    Listing = apps.get_model('home', 'TbAnuncioItemMagico')
    fields = (
        'raridade', 'requer_sintonizacao', 'detalhes_sintonizacao', 'slot', 'loja',
        'preco', 'tipo', 'descricao_markdown', 'imagem_url', 'tags_json', 'nome_ingles',
    )
    grouped = {}
    for item in Item.objects.all().order_by('pk'):
        grouped.setdefault(_norm(item.nome), []).append(item)
    for rows in grouped.values():
        if len(rows) < 2:
            continue
        signatures = {tuple(str(getattr(item, field)) for field in fields) for item in rows}
        if len(signatures) != 1:
            continue
        canonical = min(
            rows,
            key=lambda item: (bool(re.search(r'-\d+$', item.slug or '')), len(item.slug or ''), item.pk),
        )
        for duplicate in rows:
            if duplicate.pk == canonical.pk:
                continue
            Inventory.objects.filter(id_item_magico_id=duplicate.pk).update(
                id_item_magico_id=canonical.pk)
            Listing.objects.filter(id_item_magico_id=duplicate.pk).update(
                id_item_magico_id=canonical.pk)
            duplicate.delete()

    # Estes dois pares não são cópias: o nome é que escondia a diferença mecânica.
    Item.objects.filter(slug='pocao-de-cura-superior').update(nome='Poção de Cura Maior')
    for slug, suffix in (
        ('lanca-da-contra-ataque', 'Azagaia'),
        ('lanca-da-contra-ataque-2', 'Lança'),
    ):
        Item.objects.filter(slug=slug).update(nome='Lança da Contra-Ataque (%s)' % suffix)


